import json
from itertools import permutations

def solve():
    houses = [0, 1, 2, 3]  # 0-based indices for houses 1..4
    names = ['Eric', 'Peter', 'Alice', 'Arnold']
    car_models = ['tesla model 3', 'honda civic', 'toyota camry', 'ford f150']
    birthday_month = ['jan', 'april', 'sept', 'feb']
    hobby = ['painting', 'cooking', 'gardening', 'photography']

    def pos(lst, val):
        return lst.index(val)

    for name_perm in permutations(names):
        # Clue 2 and 3 with Clue 10 implies:
        # Alice (photography) is left of Eric and left of Peter
        if not (pos(name_perm, 'Alice') < pos(name_perm, 'Eric')):
            continue
        if not (pos(name_perm, 'Alice') < pos(name_perm, 'Peter')):
            continue

        for car_perm in permutations(car_models):
            # Clue 4: Honda Civic is directly left of Tesla Model 3
            if pos(car_perm, 'honda civic') != pos(car_perm, 'tesla model 3') - 1:
                continue

            # Clue 6: Tesla Model 3 is Arnold
            if pos(car_perm, 'tesla model 3') != pos(name_perm, 'Arnold'):
                continue

            # Clue 8: Toyota Camry is Peter
            if pos(car_perm, 'toyota camry') != pos(name_perm, 'Peter'):
                continue

            for month_perm in permutations(birthday_month):
                # Clue 1: January not in the second house (house index 1)
                if month_perm[1] == 'jan':
                    continue

                # Clue 9: April is Arnold
                if pos(month_perm, 'april') != pos(name_perm, 'Arnold'):
                    continue

                # Clue 11: Peter is January
                if pos(month_perm, 'jan') != pos(name_perm, 'Peter'):
                    continue

                for hobby_perm in permutations(hobby):
                    # Clue 7: February person loves cooking
                    if pos(month_perm, 'feb') != pos(hobby_perm, 'cooking'):
                        continue

                    # Clue 2: Photography left of Eric
                    if not (pos(hobby_perm, 'photography') < pos(name_perm, 'Eric')):
                        continue

                    # Clue 3: Photography left of Peter
                    if not (pos(hobby_perm, 'photography') < pos(name_perm, 'Peter')):
                        continue

                    # Clue 5: One house between Tesla Model 3 and Gardening
                    if abs(pos(car_perm, 'tesla model 3') - pos(hobby_perm, 'gardening')) != 2:
                        continue

                    # Clue 10: Alice is the photography enthusiast
                    if pos(name_perm, 'Alice') != pos(hobby_perm, 'photography'):
                        continue

                    # Found a valid solution
                    header = ["House", "name", "car models", "birthday month", "hobby"]
                    rows = []
                    for h in houses:
                        rows.append([
                            str(h + 1),
                            name_perm[h],
                            car_perm[h],
                            month_perm[h],
                            hobby_perm[h]
                        ])

                    return {
                        "solution": {
                            "header": header,
                            "rows": rows
                        }
                    }

    return {"solution": {"header": [], "rows": []}}

if __name__ == "__main__":
    result = solve()
    print(json.dumps(result, ensure_ascii=False, indent=2))
